# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HADİSTEN HAYATA: SÜNNETİN HAYATI İNŞA EDİCİ BOYUTLARI</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. İbadette İtidal ve Süreklilik</text>\n  <text x="38" y="98" font-size="11" fill="#1e3a8a">• Aşırılıktan (ifrat) ve</text>\n  <text x="46" y="114" font-size="11" fill="#1e3a8a">gevşeklikten (tefrit) uzaklık</text>\n  <text x="38" y="138" font-size="11" fill="#1e3a8a">• Ruhbanlığın reddi; dünya ve</text>\n  <text x="46" y="154" font-size="11" font-weight="bold" fill="#1d4ed8">ahiret dengesinin korunması</text>\n  <text x="38" y="178" font-size="11" fill="#1e3a8a">• "Amellerin en sevimlisi,</text>\n  <text x="46" y="194" font-size="11" font-weight="bold" fill="#1d4ed8">az da olsa devamlı olanıdır."</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Bireysel Ahlak İnşası</text>\n  <text x="260" y="98" font-size="11" fill="#14532d">• Niyet halisliği (İhlas)</text>\n  <text x="260" y="120" font-size="11" fill="#14532d">• "Ameller niyetlere göredir."</text>\n  <text x="260" y="142" font-size="11" fill="#14532d">• Doğruluk (sıdk), emanet,</text>\n  <text x="268" y="158" font-size="11" fill="#14532d">tevazu, sabır ve şükür</text>\n  <text x="260" y="182" font-size="11" font-weight="bold" fill="#15803d">• Söz ve eylem bütünlüğü</text>\n  <text x="268" y="198" font-size="11" fill="#14532d">(Üsve-i Hasene örnekliği)</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. Toplumsal Huzur ve Güven</text>\n  <text x="483" y="98" font-size="11" fill="#78350f">• "Müslüman, elinden ve dilinden</text>\n  <text x="491" y="114" font-size="11" font-weight="bold" fill="#b45309">insanların güvende olduğu kişidir."</text>\n  <text x="483" y="138" font-size="11" fill="#78350f">• Sıla-i rahim ve komşuluk hakkı</text>\n  <text x="483" y="160" font-size="11" fill="#78350f">• Merhamet, yardımlaşma ve</text>\n  <text x="491" y="176" font-size="11" fill="#78350f">kul hakkı duyarlılığı</text>\n  <text x="483" y="198" font-size="11" font-weight="bold" fill="#92400e">• Kolaylaştırma, nefret ettirmeme</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SÜNNETE İTTİBADA ŞEKİL VE HİKMET (ÖZ) BÜTÜNLÜĞÜ</text>\n  <rect x="30" y="48" width="290" height="190" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="175" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Sünnetin Evrensel Gayeleri</text>\n  <text x="45" y="98" font-size="12" fill="#0c4a6e">• Kulun Allah ile bağını canlı tutmak</text>\n  <text x="45" y="122" font-size="12" fill="#0c4a6e">• İbadetlerin rükün ve adabını korumak</text>\n  <text x="45" y="146" font-size="12" fill="#0c4a6e">• İnsan onurunu ve kul hakkını güvenceye almak</text>\n  <text x="45" y="170" font-size="12" fill="#0c4a6e">• Dini bidat ve hurafelerden arındırmak</text>\n  <rect x="45" y="186" width="260" height="38" rx="6" fill="#ffffff" stroke="#38bdf8" stroke-width="1.5"/>\n  <text x="175" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#0369a1">Hedef: Bilinçli İttiba (Şuurlu Uyma)</text>\n\n  <rect x="355" y="48" width="315" height="190" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="512" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Kaçınılması Gereken İki Uç Yaklaşım</text>\n  <rect x="370" y="88" width="285" height="62" rx="6" fill="#ffffff" stroke="#c084fc" stroke-width="1.5"/>\n  <text x="512" y="108" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">1. Hikmeti Unutan Şekilcilik</text>\n  <text x="512" y="126" text-anchor="middle" font-size="11" fill="#581c87">Sünnetin dış görünüşünü alıp adalet, merhamet,</text>\n  <text x="512" y="142" text-anchor="middle" font-size="11" fill="#581c87">emanet ve nezaket ahlakını ihmal etmek.</text>\n\n  <rect x="370" y="160" width="285" height="62" rx="6" fill="#ffffff" stroke="#c084fc" stroke-width="1.5"/>\n  <text x="512" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">2. Sünneti Devre Dışı Bırakmak</text>\n  <text x="512" y="198" text-anchor="middle" font-size="11" fill="#581c87">"Bize yalnız Kur\'an yeter" iddiasıyla Hz. Peygamber\'in</text>\n  <text x="512" y="214" text-anchor="middle" font-size="11" fill="#581c87">tebyin ve teşri yetkisini reddetmek.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">1. ÜNİTE KAVRAM HARİTASI: PEYGAMBERİMİZE İTAAT VE BAĞLILIK</text>\n  <!-- Ust 3 Kutu: Peygamberlik Gorevleri -->\n  <rect x="25" y="46" width="205" height="90" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Nübüvvet Görevleri</text>\n  <text x="38" y="88" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Tebliğ:</tspan> Vahyi eksiksiz iletmek</text>\n  <text x="38" y="106" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Tebyin:</tspan> Vahyi açıklamak</text>\n  <text x="38" y="124" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Teşri &amp; Tezkiye:</tspan> Hüküm &amp; arındırma</text>\n\n  <rect x="247" y="46" width="205" height="90" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Bağlılık Kavramları</text>\n  <text x="260" y="88" font-size="11" fill="#14532d">• <tspan font-weight="bold">İtaat &amp; İttiba:</tspan> Uyma ve izleme</text>\n  <text x="260" y="106" font-size="11" fill="#14532d">• <tspan font-weight="bold">Üsve-i Hasene:</tspan> En güzel örnek</text>\n  <text x="260" y="124" font-size="11" fill="#14532d">• <tspan font-weight="bold">İ\'tisâm:</tspan> Kitap ve Sünnet\'e sarılma</text>\n\n  <rect x="470" y="46" width="205" height="90" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="572" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Sakınılacak Sapmalar</text>\n  <text x="483" y="88" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Bidat:</tspan> Dinde sonradan uydurulan</text>\n  <text x="483" y="106" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Hurafe:</tspan> Batıl ve asılsız inanç</text>\n  <text x="483" y="124" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Hevâ:</tspan> Nefsin bencil arzuları</text>\n\n  <!-- Alt Kutu: Temel Deliller -->\n  <rect x="25" y="152" width="650" height="90" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="174" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">TEMEL AYET VE HADİS DAYANAKLARI</text>\n  <text x="45" y="196" font-size="11" fill="#78350f">• <tspan font-weight="bold">Ahzâb 21:</tspan> "Andolsun, Allah\'ın Resulünde sizin için güzel bir örnek (üsve-i hasene) vardır."</text>\n  <text x="45" y="214" font-size="11" fill="#78350f">• <tspan font-weight="bold">Haşr 7:</tspan> "Peygamber size ne verdiyse onu alın, neyi de size yasakladıysa ondan vazgeçin."</text>\n  <text x="45" y="232" font-size="11" fill="#78350f">• <tspan font-weight="bold">Sekaleyn Hadisi:</tspan> "Size iki emanet bırakıyorum; onlara sarıldıkça sapmazsınız: Allah\'ın Kitabı ve Sünnetim."</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
